            Quiz("墾田永年私財法が出された年は？", "743 年", listOf("743 年", "723 年", "701 年", "794 年"), "初期荘園の始まり。"),
            Quiz("承久の乱の後に設置された機関は？", "六波羅探題", listOf("六波羅探題", "鎌倉府", "問注所", "京都所司代"), "1221 年、朝廷監視。"),
            Quiz("応仁の乱の開始年は？", "1467 年", listOf("1467 年", "1441 年", "1493 年", "1392 年"), "〜1477 年、下剋上へ。"),
            Quiz("参勤交代を制度化した将軍は？", "徳川家光", listOf("徳川家光", "徳川家康", "徳川秀忠", "徳川綱吉"), "寛永の武家諸法度 1635。"),
            Quiz("寛政の改革を行ったのは？", "松平定信", listOf("松平定信", "徳川吉宗", "田沼意次", "水野忠邦"), "1787〜93。"),
            Quiz("日米修好通商条約を結んだ大老は？", "井伊直弼", listOf("井伊直弼", "阿部正弘", "堀田正睦", "安藤信正"), "1858 年、無勅許調印。"),
            Quiz("地租改正での当初の税率は地価の何％？", "3%", listOf("3%", "2.5%", "5%", "1%"), "一揆で 1877 年に 2.5%。"),
